function findPrimeNumbers(arr) {
  for (let i = 0; i < arr.length; i++) {
    // Check if the current number is positive and greater than 1
    if (arr[i] > 1 && typeof arr[i] === "number") {
      let isPrime = true;

      // Check if the number is divisible by any integer from 2 to its square root
      for (let j = 2; j * j <= arr[i]; j++) {
        if (arr[i] % j === 0) {
          isPrime = false;
          break; // Number is not prime, no need to continue checking
        }
      }

      // Print the prime number if found
      if (isPrime) {
        console.log(`Found prime number: ${arr[i]}`);
      }
    }
  }
}

// Example usage:
