	% Draw the chessboard based on board dimensions
	\begin{tikzpicture}[baseline=(current bounding box.center)]
	\foreach \y in {1,...,\boardheight} {
		\foreach \x in {1,...,\boardwidth} {
			\node[square, fill=\ifnum\x>\StrMid{\boardwidth}{\StrLen{\boardwidth}}{}\or\ifnum\y>\StrMid{\boardwidth}{1}{\StrLength{\boardwidth}}{}\draw style, anchor=center] at (\x,\y) {};
